SELECT id, page, duration_sec, session_id, event_time, FIRST_VALUE(session_id) OVER (PARTITION BY page ORDER BY duration_sec DESC, id) AS first_session_id, ROUND(AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), 2) AS duration_sec_moving_avg_4 FROM web_events;
